<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { searchXiaomiCities } from '../services/weather'
import { fetchQuoteCategories, readQuoteFile } from '../services/quotes'
import { getPlatform } from '../services/platform'
import { chooseAndSaveFile, checkDesktopUpdate, downloadDesktopUpdate, isDesktop as detectDesktop, setDesktopAutostart, setDesktopUriRegistration } from '../services/desktop'
import { useSettingsStore } from '../stores/settings'
import { useContentStore } from '../stores/content'
import { useWeatherStore } from '../stores/weather'
import { FILING_NAME, FILING_URL } from '../config/branding'
import QuoteSourcePanel from '../components/QuoteSourcePanel.vue'
import LocalQuoteSourcePanel from '../components/LocalQuoteSourcePanel.vue'

const emit = defineEmits(['close'])
const props = defineProps({ desktopAvailable: { type: Boolean, default: false } })
const isDesktop = () => props.desktopAvailable || detectDesktop()
const settingsStore = useSettingsStore()
const contentStore = useContentStore()
const weatherStore = useWeatherStore()
const draft = reactive({
  ...settingsStore.settings,
  quoteLocalSources: JSON.parse(JSON.stringify(settingsStore.settings.quoteLocalSources || {})),
  quoteSources: JSON.parse(JSON.stringify(settingsStore.settings.quoteSources || {})),
  quoteApiCategoryWeights: JSON.parse(JSON.stringify(settingsStore.settings.quoteApiCategoryWeights || {}))
})
const activePane = ref('startup')
const activeGroup = ref(null)
const groups = [
  { id: 'workspace', label: '基础功能', description: '启动、显示与课程', icon: 'options-20-regular', items: [{ id: 'startup', label: '启动页面', icon: 'clock-20-regular' }, { id: 'display', label: '显示内容', icon: 'eye-20-regular' }, { id: 'countdown', label: '重要日', icon: 'timer-20-regular' }, { id: 'schedule', label: '课程表', icon: 'calendar-20-regular' }] },
  { id: 'appearance', label: '视觉外观', description: '颜色、字体与背景', icon: 'color-20-regular', items: [{ id: 'overall', label: '整体样式', icon: 'color-20-regular' }, { id: 'time', label: '时间显示', icon: 'clock-20-regular' }, { id: 'layout', label: '组件布局', icon: 'panel-left-20-regular' }, { id: 'quoteStyle', label: '语录样式', icon: 'text-20-regular' }] },
  { id: 'environment', label: '环境提醒', description: '天气、通知与常亮', icon: 'alert-20-regular', items: [{ id: 'weather', label: '天气服务', icon: 'weather-partly-cloudy-day-20-regular' }, { id: 'location', label: '定位服务', icon: 'location-20-regular' }] },
  { id: 'content', label: '内容语录', description: '刷新、显示与渠道管理', icon: 'book-open-20-regular', items: [{ id: 'refresh', label: '刷新策略', icon: 'arrow-clockwise-20-regular' }, { id: 'effects', label: '显示效果', icon: 'sparkle-20-regular' }, { id: 'channels', label: '语录渠道', icon: 'book-open-20-regular' }] },
  { id: 'system', label: '系统数据', description: '校时、导入导出与更新', icon: 'database-20-regular', items: [{ id: 'calibration', label: '时间校准', icon: 'time-and-weather-20-regular' }, { id: 'updates', label: '应用更新', icon: 'arrow-sync-20-regular' }, { id: 'data', label: '设置数据', icon: 'database-20-regular' }] }
]
const startupModeOptions = [{ value: 'clock', label: '时钟' }, { value: 'countdown', label: '倒计时' }, { value: 'timer', label: '计时器' }]
const fontOptions = [{ value: 'wengfaluosi', label: '翁法罗斯（默认）' }, { value: 'system', label: '系统字体' }, { value: 'mono', label: '等宽数字' }, { value: 'serif', label: '衬线数字' }]
const backgroundOptions = [{ value: 'mica', label: 'Mica' }, { value: 'acrylic', label: 'Acrylic' }, { value: 'solid', label: '纯色' }]
const animationOptions = [{ value: 'typewriter', label: '自然打字' }, { value: 'crossfade', label: '平滑显示' }, { value: 'none', label: '直接显示' }]
const typeSpeedOptions = [{ value: 'slow', label: '慢速' }, { value: 'standard', label: '标准' }, { value: 'fast', label: '快速' }]
const weekdayOptions = [{ value: 1, label: '周一' }, { value: 2, label: '周二' }, { value: 3, label: '周三' }, { value: 4, label: '周四' }, { value: 5, label: '周五' }, { value: 6, label: '周六' }, { value: 0, label: '周日' }]
const subjectOptions = ['语文', '数学', '英语', '物理', '化学', '生物', '历史', '政治', '地理', '其他'].map(value => ({ value, label: value }))
const scheduleTabs = [{ value: 'overview', label: '概览' }, { value: 'library', label: '课程库' }, { value: 'daily', label: '日课程表' }]
const scheduleTab = ref('overview')
const scheduleDay = ref(1)
const scheduleDayLessons = computed(() => contentStore.content.schedule.filter(item => item.weekday === Number(scheduleDay.value)).sort((a, b) => a.startAt.localeCompare(b.startAt)))
const scheduleCourses = computed(() => [...new Map(contentStore.content.schedule.map(item => [item.subject, item])).values()])
const todayLessons = computed(() => contentStore.content.schedule.filter(item => item.weekday === new Date().getDay()).sort((a, b) => a.startAt.localeCompare(b.startAt)))

const importantName = ref('')
const importantDate = ref('')
const quoteDraft = ref('')
const quoteImportInput = ref(null)
const importInput = ref(null)
const lessonSubject = ref('')
const lessonWeekday = ref(1)
const lessonStart = ref('08:00')
const lessonEnd = ref('08:45')
const lessonRoom = ref('')
const editingLessonId = ref(null)
const cityResults = ref([])
const citySearchOpen = ref(false)
const citySearchLoading = ref(false)
const quoteCategories = ref([])
const quoteCategoryLoading = ref(false)
const quoteConfigOpen = ref(false)
const platformLabel = ref('PWA')
const saved = ref(false)
const appVersion = __APP_VERSION__
const buildId = __BUILD_ID__
const autostartMessage = ref('')
const feedbackMessage = ref('')
const uriHelpOpen = ref(false)
const uriMessage = ref('')
const updateState = reactive({ checking: false, available: false, version: '', url: '', message: '' })
const desktopMode = computed(() => props.desktopAvailable || isDesktop())
let citySearchTimer
let citySearchController

function enterGroup(group) { activeGroup.value = group; activePane.value = group.items[0]?.id || activePane.value }
function selectPane(pane) { activePane.value = pane }
function save() {
  settingsStore.update({ ...draft })
  saved.value = true
  window.clearTimeout(save.timer)
  save.timer = window.setTimeout(() => { saved.value = false }, 1800)
}
function cancel() { emit('close') }
function daysUntil(date) { return Math.max(0, Math.ceil((new Date(`${date}T00:00:00`).getTime() - Date.now()) / 86400000)) }
function addImportant() { contentStore.addImportantDay(importantName.value.trim(), importantDate.value); importantName.value = ''; importantDate.value = '' }
function addQuote() { contentStore.addQuote(quoteDraft.value); quoteDraft.value = '' }
function addLesson() { const lesson = { subject: lessonSubject.value.trim() || '未命名课程', weekday: Number(lessonWeekday.value), startAt: lessonStart.value, endAt: lessonEnd.value, room: lessonRoom.value.trim() }; const existing = contentStore.content.schedule.find(item => item.id === editingLessonId.value); if (existing) contentStore.updateLesson(existing, lesson); else contentStore.addLesson(lesson); editingLessonId.value = null; lessonSubject.value = ''; lessonRoom.value = '' }
function editLesson(lesson) { editingLessonId.value = lesson.id; lessonSubject.value = lesson.subject; lessonWeekday.value = lesson.weekday; lessonStart.value = lesson.startAt; lessonEnd.value = lesson.endAt; lessonRoom.value = lesson.room || '' }
function cancelLessonEdit() { editingLessonId.value = null; lessonSubject.value = ''; lessonRoom.value = '' }
async function importQuotes(event) { const file = event.target.files?.[0]; if (!file) return; try { contentStore.addQuotes(await readQuoteFile(file)); feedbackMessage.value = '语录已导入' } catch { feedbackMessage.value = '金句文件格式无效' }; event.target.value = '' }
async function refreshQuoteCategories() { quoteCategoryLoading.value = true; try { quoteCategories.value = await fetchQuoteCategories(); if (!quoteCategories.value.length) quoteCategories.value = ['崩铁', '名人名言', '原神', '学习', '校园'] } catch { quoteCategories.value = ['崩铁', '名人名言', '原神', '学习', '校园'] } finally { quoteCategoryLoading.value = false } }
function toggleQuoteCategory(category) { const selected = new Set(draft.quoteApiCategories || []); if (selected.has(category)) selected.delete(category); else selected.add(category); draft.quoteApiCategories = [...selected] }
function openQuoteConfig() { quoteConfigOpen.value = true; refreshQuoteCategories() }
function toggleCategoryWeights() {
  draft.quoteApiCategoryWeightsEnabled = !draft.quoteApiCategoryWeightsEnabled
  if (!draft.quoteApiCategoryWeightsEnabled) return
  if (!draft.quoteApiCategoryWeights || typeof draft.quoteApiCategoryWeights !== 'object') draft.quoteApiCategoryWeights = {}
  for (const category of draft.quoteApiCategories || []) {
    if (draft.quoteApiCategoryWeights[category] === undefined) draft.quoteApiCategoryWeights[category] = 1
  }
}
function categoryWeight(category) { return draft.quoteApiCategoryWeights?.[category] ?? 1 }
function setCategoryWeight(category, event) {
  if (!draft.quoteApiCategoryWeights || typeof draft.quoteApiCategoryWeights !== 'object') draft.quoteApiCategoryWeights = {}
  draft.quoteApiCategoryWeights[category] = Math.max(0, Number(event.target.value) || 0)
}
async function downloadData() { const payload = JSON.stringify({ version: 2, settings: settingsStore.settings, content: contentStore.content, time: JSON.parse(localStorage.getItem('cytime.time-state.v1') || '{}') }, null, 2); feedbackMessage.value = await chooseAndSaveFile(payload, `cytime-backup-${new Date().toISOString().slice(0, 10)}.json`) ? '备份已保存到你选择的位置' : '已取消保存或当前环境不支持文件选择' }
async function importData(event) { const file = event.target.files?.[0]; if (!file) return; try { const payload = JSON.parse(await file.text()); if (payload.settings) localStorage.setItem('cytime.settings.v2', JSON.stringify(payload.settings)); if (payload.content) localStorage.setItem('cytime.content.v1', JSON.stringify(payload.content)); if (payload.time) localStorage.setItem('cytime.time-state.v1', JSON.stringify(payload.time)); window.location.reload() } catch { feedbackMessage.value = '备份文件格式无效' } finally { event.target.value = '' } }
function clearData() { if (!window.confirm('确定要清除 CyTime 的本地数据吗？此操作无法撤销。')) return; ['cytime.settings.v2', 'cytime.settings.v1', 'cytime.content.v1', 'cytime.time-state.v1'].forEach(key => localStorage.removeItem(key)); window.location.reload() }
function resetSettings() { if (!window.confirm('恢复默认设置，但保留课程、作业和重要日吗？')) return; settingsStore.reset(); window.location.reload() }
function reloadApp() { window.location.reload() }
async function checkForUpdate() { updateState.checking = true; try { const latest = await checkDesktopUpdate(); const current = appVersion; updateState.version = latest.tag_name || ''; updateState.url = latest.html_url || ''; updateState.available = Boolean(updateState.version && updateState.version.replace(/^v/, '') !== current); updateState.message = updateState.available ? `发现新版本 ${updateState.version}` : `当前已是最新版本 v${current}` } catch (error) { updateState.message = error?.message || '检查更新失败' } finally { updateState.checking = false } }
async function installUpdate() { if (updateState.url) await downloadDesktopUpdate(updateState.url) }
async function requestNotifications() { if (typeof Notification === 'undefined') return; const permission = await Notification.requestPermission(); if (permission === 'granted') draft.notificationEnabled = true }
function openCitySearch() { citySearchOpen.value = true; scheduleCitySearch() }
function scheduleCitySearch() { window.clearTimeout(citySearchTimer); citySearchTimer = window.setTimeout(searchCities, 240) }
async function searchCities() { const query = draft.weatherCityName.trim(); if (!query) { cityResults.value = []; return }; citySearchController?.abort(); citySearchController = new AbortController(); citySearchLoading.value = true; try { cityResults.value = await searchXiaomiCities(query, citySearchController.signal) } catch (error) { if (error?.name !== 'AbortError') cityResults.value = [] } finally { citySearchLoading.value = false } }
function selectCity(city) { draft.weatherCityName = city.name; draft.weatherCityNum = city.locationKey.replace(/^weathercn:/, ''); citySearchOpen.value = false }
function closeCitySearch() { window.setTimeout(() => { citySearchOpen.value = false }, 160) }
function refreshWeather() { weatherStore.refresh(draft.weatherCityNum, true) }
async function toggleAutostart() { if (!desktopMode.value) return; autostartMessage.value = '正在请求权限…'; try { const enabled = await setDesktopAutostart(!draft.autostart); draft.autostart = enabled; settingsStore.update({ autostart: enabled }); autostartMessage.value = enabled ? '已启用，登录后将在托盘后台运行' : '已关闭'; } catch (error) { autostartMessage.value = error?.message || '无法更新开机自启动设置' } }
async function toggleUriRegistration() { if (!desktopMode.value) return; uriMessage.value = '正在更新 URI 注册…'; try { const enabled = await setDesktopUriRegistration(!draft.uriRegistration); draft.uriRegistration = enabled; settingsStore.update({ uriRegistration: enabled }); uriMessage.value = enabled ? '已注册 cytime:// 协议' : '已关闭 cytime:// 协议注册'; } catch (error) { uriMessage.value = error?.message || '无法更新 URI 注册' } }

watch(() => draft.weatherCityName, () => { if (citySearchOpen.value) scheduleCitySearch() })
onMounted(async () => { platformLabel.value = String(await getPlatform()).toUpperCase(); weatherStore.refresh(draft.weatherCityNum); refreshQuoteCategories() })
onBeforeUnmount(() => { window.clearTimeout(citySearchTimer); citySearchController?.abort() })
</script>

<template>
  <section class="settings-sheet" role="dialog" aria-label="设置">
    <header class="settings-header"><div class="settings-title"><FluentIcon icon="options-24-regular" :width="21" /><h1>设置</h1></div><button type="button" class="settings-close" aria-label="关闭设置" @click="cancel"><FluentIcon icon="dismiss-20-regular" :width="18" /></button></header>
    <div class="settings-workspace">
      <aside class="settings-dock">
        <template v-if="!activeGroup">
          <nav class="settings-nav settings-root-nav" aria-label="设置分类"><button v-for="group in groups" :key="group.id" type="button" class="settings-group-button" @click="enterGroup(group)"><FluentIcon :icon="group.icon" :width="18" /><span><strong>{{ group.label }}</strong><small>{{ group.description }}</small></span><FluentIcon icon="chevron-right-16-regular" :width="14" class="group-chevron" /></button></nav>
          <button type="button" class="settings-nav-project" :class="{ active: activePane === 'about' }" @click="activePane = 'about'"><FluentIcon icon="info-20-regular" :width="17" /><span>项目信息</span></button>
        </template>
        <template v-else>
          <button type="button" class="settings-dock-back" @click="activeGroup = null"><FluentIcon icon="arrow-left-20-regular" :width="18" /><span>返回</span></button>
          <div class="settings-subnav-heading"><FluentIcon :icon="activeGroup.icon" :width="18" /><div><strong>{{ activeGroup.label }}</strong><small>{{ activeGroup.description }}</small></div></div>
          <nav class="settings-nav settings-subnav" :aria-label="`${activeGroup.label}设置`"><button v-for="item in activeGroup.items" :key="item.id" type="button" class="settings-nav-item" :class="{ active: activePane === item.id }" @click="selectPane(item.id)"><FluentIcon :icon="item.icon" :width="16" /><span>{{ item.label }}</span></button></nav>
        </template>
        <div class="settings-dock-footer">CyTime 昔时时钟 · v{{ appVersion }}<template v-if="buildId"> · build {{ buildId }}</template></div>
      </aside>

      <div class="settings-main"><div class="settings-scroll"><Transition name="settings-pane" mode="out-in"><div :key="activePane" class="settings-pane-content">
        <template v-if="activePane === 'startup'"><span class="settings-kicker">基础功能</span><h2>启动页面</h2><p class="settings-lead">设置刷新或下次启动时默认进入的页面。</p><section class="setting-card"><div class="setting-card-heading"><FluentIcon icon="clock-20-regular" :width="20" /><div><h3>启动时默认页面</h3><p>设置应用打开后直接进入的模式。</p></div></div><div class="segmented-control segmented-three"><button v-for="item in startupModeOptions" :key="item.value" type="button" :class="{ active: draft.startupMode === item.value }" @click="draft.startupMode = item.value">{{ item.label }}</button></div><label v-if="isDesktop()" class="setting-select-label startup-window-select">启动窗口模式<FluentSelect v-model="draft.startupWindowMode" :options="[{ value: 'mini', label: 'Mini 1280 × 960' }, { value: 'normal', label: '常规窗口' }, { value: 'full', label: '全屏' }]" /></label></section><section class="setting-card setting-row"><div><h3>保持屏幕常亮</h3><p>前台显示时请求 Screen Wake Lock，后台由系统处理。</p></div><button type="button" class="switch" :class="{ on: draft.preventSleep }" :aria-pressed="draft.preventSleep" @click="draft.preventSleep = !draft.preventSleep"><i></i></button></section><section v-if="isDesktop()" class="setting-card setting-row"><div><h3>开机自启动</h3><p>登录 Windows 后以高权限启动并唤醒已有实例。</p><small v-if="autostartMessage" class="inline-status">{{ autostartMessage }}</small></div><button type="button" class="switch" :class="{ on: draft.autostart }" :aria-pressed="draft.autostart" @click="toggleAutostart"><i></i></button></section></template>

        <template v-else-if="activePane === 'display'"><span class="settings-kicker">基础功能</span><h2>显示内容</h2><p class="settings-lead">选择时钟页面显示的信息模块。</p><section class="setting-card"><div v-for="item in [{ key: 'showWeather', label: '天气', desc: '显示当前位置的天气概览' }, { key: 'showDayProgress', label: '每日进度', desc: '显示当天 24 小时进度' }, { key: 'showDate', label: '日期', desc: '显示当前日期和星期' }, { key: 'showQuote', label: '金句', desc: '显示本地或云端语录' }, { key: 'showClockSeconds', label: '显示秒数', desc: '在时间中显示秒' } ]" :key="item.key" class="setting-row"><div><h3>{{ item.label }}</h3><p>{{ item.desc }}</p></div><button type="button" class="switch" :class="{ on: draft[item.key] }" :aria-pressed="draft[item.key]" @click="draft[item.key] = !draft[item.key]"><i></i></button></div></section><section class="setting-card setting-row"><div><h3>作业板</h3><p>在时钟区域显示可操作的作业面板。</p></div><button type="button" class="switch" :class="{ on: draft.showHomework }" :aria-pressed="draft.showHomework" @click="draft.showHomework = !draft.showHomework"><i></i></button></section><section class="setting-card setting-row"><div><h3>课程提示</h3><p>在时钟区域显示当前或下一节课程。</p></div><button type="button" class="switch" :class="{ on: draft.showSchedule }" :aria-pressed="draft.showSchedule" @click="draft.showSchedule = !draft.showSchedule"><i></i></button></section></template>

        <template v-else-if="activePane === 'countdown'"><span class="settings-kicker">基础功能</span><h2>重要日</h2><p class="settings-lead">管理高考、考试、生日等多个目标日期。</p><section class="setting-card"><div class="card-toolbar"><div><h3>添加重要日</h3><p>目标日期到期后保留为 0 天。</p></div><div class="inline-form"><input v-model="importantName" placeholder="名称" /><FluentDatePicker v-model="importantDate" placeholder="日期" /><button type="button" class="subtle-button" @click="addImportant">添加</button></div></div><div class="managed-list"><div v-for="item in contentStore.content.importantDays" :key="item.id" class="managed-item"><span><strong>{{ item.name }}</strong><small>{{ item.date }} · 还有 {{ daysUntil(item.date) }} 天</small></span><button type="button" class="icon-text-button" @click="contentStore.removeImportantDay(item)">删除</button></div></div></section></template>

        <template v-else-if="activePane === 'schedule'"><span class="settings-kicker">基础功能</span><h2>课程表</h2><p class="settings-lead">按周循环维护课程，时钟会显示当前或下一节课。</p><div class="settings-tabs"><button v-for="tab in scheduleTabs" :key="tab.value" type="button" :class="{ active: scheduleTab === tab.value }" @click="scheduleTab = tab.value">{{ tab.label }}</button></div><template v-if="scheduleTab === 'overview'"><section class="schedule-summary-grid"><div class="setting-card"><small>今日课程</small><strong>{{ todayLessons.length }}</strong><span>{{ todayLessons.length ? '按时间顺序安排' : '今天没有课程' }}</span></div><div class="setting-card"><small>课程总数</small><strong>{{ contentStore.content.schedule.length }}</strong><span>周循环课时</span></div><div class="setting-card"><small>课程库</small><strong>{{ scheduleCourses.length }}</strong><span>不同课程</span></div></section><section class="setting-card"><h3>今日课程</h3><div v-if="todayLessons.length" class="managed-list"><div v-for="lesson in todayLessons" :key="lesson.id" class="managed-item"><span><strong>{{ lesson.subject }}</strong><small>{{ lesson.startAt }} - {{ lesson.endAt }} {{ lesson.room }}</small></span></div></div><p v-else class="empty-inline">今天没有安排课程。</p></section></template><template v-else-if="scheduleTab === 'library'"><section class="setting-card"><div class="card-toolbar"><div><h3>课程库</h3><p>课程名称来自当前周循环课时。</p></div><span class="task-total">{{ scheduleCourses.length }} 门课程</span></div><div class="managed-list"><div v-for="course in scheduleCourses" :key="course.subject" class="managed-item"><span><strong>{{ course.subject }}</strong><small>{{ course.room || '未设置教室' }}</small></span></div><p v-if="!scheduleCourses.length" class="empty-inline">还没有课程，请在日课程表添加。</p></div></section></template><template v-else-if="scheduleTab === 'daily'"><section class="setting-card"><div class="schedule-toolbar"><FluentSelect v-model="scheduleDay" :options="weekdayOptions" aria-label="查看星期" /><span>{{ scheduleDayLessons.length }} 个课时</span></div><div class="inline-form schedule-form"><input v-model="lessonSubject" placeholder="课程名称" /><FluentSelect v-model="lessonWeekday" :options="weekdayOptions" aria-label="上课星期" /><FluentTimePicker v-model="lessonStart" placeholder="开始" /><FluentTimePicker v-model="lessonEnd" placeholder="结束" /><input v-model="lessonRoom" placeholder="教室（可选）" /><button type="button" class="subtle-button" @click="addLesson">{{ editingLessonId ? '保存课程' : '添加课程' }}</button><button v-if="editingLessonId" type="button" class="subtle-button" @click="cancelLessonEdit">取消</button></div><div class="managed-list"><div v-for="lesson in scheduleDayLessons" :key="lesson.id" class="managed-item"><span><strong>{{ lesson.subject }}</strong><small>{{ lesson.startAt }} - {{ lesson.endAt }} {{ lesson.room }}</small></span><span class="managed-actions"><button type="button" class="icon-text-button" @click="editLesson(lesson)">编辑</button><button type="button" class="icon-text-button" @click="contentStore.removeLesson(lesson)">删除</button></span></div><p v-if="!scheduleDayLessons.length" class="empty-inline">这一天还没有课程。</p></div></section></template><template v-else><section class="setting-card"><h3>周期与锚点</h3><p class="setting-copy">当前版本使用周一至周日的手动循环；周期锚点用于后续扩展上课日/休息日模板。</p><div class="schedule-cycle"><span class="cycle-active">周一至周五 · 上课</span><span class="cycle-rest">周六、周日 · 休息</span></div></section></template></template>

        <template v-else-if="activePane === 'overall'"><span class="settings-kicker">视觉外观</span><h2>整体样式</h2><p class="settings-lead">调整主题、主时钟字体、材质和整体缩放。</p><section class="setting-card"><h3>主题</h3><div class="theme-options"><button type="button" class="theme-option dark-option" :class="{ selected: draft.theme === 'dark-peach' }" @click="draft.theme = 'dark-peach'"><i></i><span>深色桃粉</span></button><button type="button" class="theme-option light-option" :class="{ selected: draft.theme === 'light-peach' }" @click="draft.theme = 'light-peach'"><i></i><span>浅色桃粉</span></button></div><div class="appearance-fields"><label>数字字体<FluentSelect v-model="draft.fontFamily" :options="fontOptions" /></label><label>背景材质<FluentSelect v-model="draft.background" :options="backgroundOptions" /></label><label class="range-control">整体缩放 <strong>{{ draft.uiScale }}%</strong><input v-model.number="draft.uiScale" type="range" min="50" max="200" step="5" /></label></div></section></template>

        <template v-else-if="activePane === 'time'"><span class="settings-kicker">视觉外观</span><h2>时间显示</h2><p class="settings-lead">分别调整主时钟、日期和金句，避免模块之间比例失衡。</p><section class="setting-card"><label class="range-control">主时钟字号 <strong>{{ draft.clockFontScale }}vw</strong><input v-model.number="draft.clockFontScale" type="range" min="6" max="22" step="0.5" /></label><label class="range-control">日期字号 <strong>{{ draft.dateFontSize }}px</strong><input v-model.number="draft.dateFontSize" type="range" min="10" max="32" /></label><label class="range-control">金句字号 <strong>{{ draft.quoteFontSize }}px</strong><input v-model.number="draft.quoteFontSize" type="range" min="10" max="48" /></label></section></template>

        <template v-else-if="activePane === 'layout'"><span class="settings-kicker">视觉外观</span><h2>组件布局</h2><p class="settings-lead">微调顶部状态栏与作业板的位置和尺寸；偏移只会靠近屏幕边缘，不会超出画面。</p><section class="setting-card"><h3>顶部状态栏</h3><label class="range-control">整体缩放 <strong>{{ draft.statusDockScale }}%</strong><input v-model.number="draft.statusDockScale" type="range" min="60" max="150" step="5" /></label><label class="range-control">垂直偏移 <strong>{{ draft.statusDockOffsetY }}px</strong><input v-model.number="draft.statusDockOffsetY" type="range" min="0" max="240" step="2" /></label></section><section class="setting-card"><h3>作业板</h3><label class="range-control">面板宽度 <strong>{{ draft.homeworkWidth }}px</strong><input v-model.number="draft.homeworkWidth" type="range" min="200" max="520" step="10" /></label><label class="range-control">贴边偏移 <strong>{{ draft.homeworkOffsetX }}px</strong><input v-model.number="draft.homeworkOffsetX" type="range" min="0" max="240" step="4" /></label><p class="setting-copy">偏移方向跟随作业板所在侧：在左侧就向左贴边，在右侧就向右贴边；数值再大也只贴到屏幕边缘，不会溢出。</p></section></template>

        <template v-else-if="activePane === 'quoteStyle'"><span class="settings-kicker">视觉外观</span><h2>语录样式</h2><p class="settings-lead">设置文字出现和消失方式。</p><section class="setting-card"><label class="setting-select-label">出现动画<FluentSelect v-model="draft.quoteAnimation" :options="animationOptions" /></label><label class="setting-select-label">打字速度<FluentSelect v-model="draft.quoteTypeSpeed" :options="typeSpeedOptions" /></label></section></template>

        <template v-else-if="activePane === 'weather' || activePane === 'location'"><span class="settings-kicker">环境提醒</span><h2>{{ activePane === 'weather' ? '天气服务' : '定位服务' }}</h2><p class="settings-lead">使用小米天气数据；城市必须从搜索结果中确认。</p><section class="setting-card"><div class="city-picker wide-city-picker"><label class="setting-select-label">城市名称<input v-model="draft.weatherCityName" class="setting-input" autocomplete="off" @focus="openCitySearch" @blur="closeCitySearch" /></label><div v-if="citySearchOpen" class="city-results"><div v-if="citySearchLoading" class="city-result-message">正在搜索城市…</div><div v-else-if="!cityResults.length" class="city-result-message">输入城市名称，例如“南岸”或“杭州”</div><button v-for="city in cityResults" v-else :key="city.locationKey" type="button" class="city-result" @mousedown.prevent="selectCity(city)"><strong>{{ city.name }}</strong><span>{{ city.affiliation || '中国' }} · {{ city.locationKey }}</span></button></div></div><p class="setting-copy">当前地区标识：{{ draft.weatherCityNum ? `weathercn:${draft.weatherCityNum}` : '尚未确认' }}</p><div v-if="activePane === 'weather'" class="weather-settings-grid"><div class="weather-refresh-row"><span>天气数据</span><button type="button" class="subtle-button" @click="refreshWeather">刷新天气</button></div><div class="weather-summary" v-if="weatherStore.current"><div><small>当前天气</small><strong>{{ weatherStore.currentLabel }}</strong></div><div><small>温度</small><strong>{{ weatherStore.current.temperature?.value }}{{ weatherStore.current.temperature?.unit || '℃' }}</strong></div><div><small>体感</small><strong>{{ weatherStore.current.feelsLike?.value || '--' }}℃</strong></div><div><small>湿度</small><strong>{{ weatherStore.current.humidity?.value || '--' }}%</strong></div><div><small>风速</small><strong>{{ weatherStore.current.wind?.speed?.value || '--' }}{{ weatherStore.current.wind?.speed?.unit || '' }}</strong></div></div><label class="setting-row"><span>天气预警弹窗</span><input type="checkbox" v-model="draft.weatherAlertEnabled" /></label><label class="setting-row"><span>显示次日预报</span><input type="checkbox" v-model="draft.weatherForecastEnabled" /></label></div></section></template>

        <template v-else-if="activePane === 'refresh'"><span class="settings-kicker">内容语录</span><h2>刷新策略</h2><p class="settings-lead">控制语录是否自动轮换以及轮换频率。</p><section class="setting-card"><div class="setting-row"><div><h3>自动轮换</h3><p>关闭后保留当前语录。</p></div><button type="button" class="switch" :class="{ on: draft.quoteRotation }" @click="draft.quoteRotation = !draft.quoteRotation"><i></i></button></div><label class="range-control">刷新频率 <strong>{{ draft.quoteInterval }} 秒</strong><input v-model.number="draft.quoteInterval" type="range" min="30" max="1800" step="30" /></label></section></template>
        <template v-else-if="activePane === 'effects'"><span class="settings-kicker">内容语录</span><h2>显示效果</h2><p class="settings-lead">设置文字出现和消失方式。</p><section class="setting-card"><label class="setting-select-label">出现动画<FluentSelect v-model="draft.quoteAnimation" :options="animationOptions" /></label><label class="setting-select-label">打字速度<FluentSelect v-model="draft.quoteTypeSpeed" :options="typeSpeedOptions" /></label></section></template>
         <template v-else-if="activePane === 'channels'"><span class="settings-kicker">内容语录</span><h2>语录渠道</h2><p class="settings-lead">管理本地内容、云端来源和抽取权重。</p><LocalQuoteSourcePanel :draft="draft" :content="contentStore.content" /><QuoteSourcePanel :draft="draft" @configure="openQuoteConfig" /><section class="setting-card"><div class="card-toolbar"><div><h3>日常励志内容</h3><p>TXT 每行一条；JSON 可使用 `{ "text": "...", "author": "...", "work": "..." }`。</p></div><div class="inline-form"><input v-model="quoteDraft" placeholder="添加一句语录" /><button type="button" class="subtle-button" @click="addQuote">添加</button><button type="button" class="subtle-button" @click="quoteImportInput?.click()">导入</button><input ref="quoteImportInput" type="file" accept=".txt,.json" hidden @change="importQuotes" /></div></div><div class="managed-list"><div v-for="quote in contentStore.content.quotes" :key="quote" class="managed-item"><span>{{ quote }}</span><button type="button" class="icon-text-button" @click="contentStore.removeQuote(quote)">删除</button></div></div></section></template>

        <template v-else-if="activePane === 'calibration'"><span class="settings-kicker">系统数据</span><h2>时间校准</h2><p class="settings-lead">浏览器时钟作为默认时间源；后续 Tauri 端可增加 NTP。</p><section class="setting-card"><div class="setting-row"><div><h3>自动校时</h3><p>定期从 HTTP Date 服务测量偏移，不修改系统时间。</p></div><button type="button" class="switch" :class="{ on: draft.timeSyncEnabled }" @click="draft.timeSyncEnabled = !draft.timeSyncEnabled"><i></i></button></div><label class="range-control">校时间隔 <strong>{{ draft.timeSyncInterval }} 分钟</strong><input v-model.number="draft.timeSyncInterval" type="range" min="5" max="360" step="5" /></label></section></template>
         <template v-else-if="activePane === 'updates'"><span class="settings-kicker">系统数据</span><h2>应用更新</h2><p class="settings-lead">检查 GitHub Release，发现新版本后可打开下载页。</p><section class="setting-card"><div class="setting-row"><div><h3>当前版本</h3><p>v26.0.1 · {{ platformLabel }}</p><small v-if="updateState.message" class="inline-status">{{ updateState.message }}</small></div><div class="update-actions"><button type="button" class="subtle-button" :disabled="updateState.checking" @click="checkForUpdate">{{ updateState.checking ? '检查中…' : '检查更新' }}</button><button v-if="updateState.available" type="button" class="save-button" @click="installUpdate">安装更新</button></div></div></section></template>
        <template v-else-if="activePane === 'data'"><span class="settings-kicker">系统数据</span><h2>设置数据</h2><p class="settings-lead">本地任务、设置、语录、课程和作业均可备份。</p><section class="setting-card"><div class="data-actions"><button type="button" class="subtle-button" @click="downloadData">导出全部数据</button><button type="button" class="subtle-button" @click="importInput?.click()">导入备份</button><input ref="importInput" type="file" accept="application/json" hidden @change="importData" /><button type="button" class="subtle-button" @click="resetSettings">恢复默认设置</button><button type="button" class="subtle-button danger-button" @click="clearData">清除本地数据</button></div><p class="setting-copy">当前平台：{{ platformLabel }}。数据只保存在此设备。</p></section></template>
         <template v-else-if="activePane === 'about'"><span class="settings-kicker">关于</span><h2>项目信息</h2><p class="settings-lead">一款面向学生与教育场景的班级大屏时钟。</p><section class="setting-card about-card"><div class="about-hero"><img class="about-app-mark" src="/icon-192.svg" alt="CyTime" /><h3>CyTime 昔时时钟</h3><strong>v{{ appVersion }}<template v-if="buildId"> · build {{ buildId }}</template></strong><p>昔光涟涟，时不我待。</p></div><div class="about-credit-row"><div class="about-person"><img src="/avatars/Cyrene2008.png" alt="Cyrene2008" /><div><strong>Cyrene2008 <small>作者</small></strong><a class="project-link" href="https://github.com/Cyrene2008" target="_blank" rel="noreferrer">GitHub</a></div></div><div class="about-powered"><h3>Powered by VueFluentWidgets</h3><p>Fluent Design System for Vue · MIT License</p><p>Copyright © 2025-2026 Cyrene2008</p><a class="project-link" href="https://fluent.cyrene.hk" target="_blank" rel="noreferrer">VueFluentWidgets 官网</a></div></div><div class="about-license"><strong>开源许可</strong><p>GNU General Public License v3.0</p><p>CyTime 源码与组件库信息可在对应仓库查看。</p><div class="project-links"><a class="project-link" href="https://github.com/Cyrene2008/CyTime" target="_blank" rel="noreferrer">CyTime 仓库</a><a class="project-link" href="https://github.com/Cyrene2008/VueFluentWidgets" target="_blank" rel="noreferrer">VueFluentWidgets</a><a v-if="FILING_NAME" class="project-link" :href="FILING_URL" target="_blank" rel="noreferrer">{{ FILING_NAME }}</a></div></div></section></template>
        <section v-if="activePane === 'startup' && isDesktop()" class="setting-card setting-row uri-setting"><div><h3>URI 注册</h3><p>允许其他程序通过 cytime:// 唤醒 CyTime 并执行受限操作。</p><small v-if="uriMessage" class="inline-status">{{ uriMessage }}</small></div><div class="uri-setting-actions"><button type="button" class="subtle-button" @click="uriHelpOpen = true"><FluentIcon icon="info-20-regular" :width="16" />使用说明</button><button type="button" class="switch" :class="{ on: draft.uriRegistration }" :aria-pressed="draft.uriRegistration" @click="toggleUriRegistration"><i></i></button></div></section>
       </div></Transition></div><footer class="settings-actions"><span v-if="saved" class="save-message">已保存</span><span v-if="feedbackMessage" class="save-message">{{ feedbackMessage }}</span><button type="button" class="subtle-button action-button" @click="cancel">取消</button><button type="button" class="save-button action-button" @click="save">保存</button></footer></div>
    </div>
    <div v-if="uriHelpOpen" class="uri-help-layer" role="dialog" aria-modal="true" aria-label="URI 使用说明" @click.self="uriHelpOpen = false"><section class="uri-help-modal"><header><div><span class="settings-kicker">桌面端</span><h2>URI 使用说明</h2></div><button type="button" class="dialog-close" aria-label="关闭说明" @click="uriHelpOpen = false"><FluentIcon icon="dismiss-20-regular" :width="18" /></button></header><div class="uri-help-content"><p>启用 URI 注册后，系统会将 cytime:// 链接交给 CyTime 处理。URI 只控制主页面和主任务。</p><dl><dt>启动程序</dt><dd><code>cytime://</code></dd><dt>指定窗口模式</dt><dd><code>cytime://?mode=mini</code>、<code>normal</code>、<code>max</code> 或 <code>full</code></dd><dt>切换页面</dt><dd><code>cytime://page/time</code><br /><code>cytime://page/countdown</code><br /><code>cytime://page/timer</code></dd><dt>创建倒计时</dt><dd><code>cytime://countdown?target=20261101121500</code><br /><code>cytime://countdown?length=1800</code></dd><dt>控制主倒计时</dt><dd><code>cytime://task/countdown/pause</code><br /><code>cytime://task/countdown/continue</code><br /><code>cytime://task/countdown/stop</code></dd></dl></div><footer><button type="button" class="save-button" @click="uriHelpOpen = false">知道了</button></footer></section></div>
    <div v-if="quoteConfigOpen" class="uri-help-layer" role="dialog" aria-modal="true" aria-label="CyQuote 昔言 · 分类" @click.self="quoteConfigOpen = false"><section class="uri-help-modal quote-config-modal"><header><div><span class="settings-kicker">云端来源</span><h2>CyQuote 昔言 · 分类</h2></div><button type="button" class="dialog-close" aria-label="关闭分类配置" @click="quoteConfigOpen = false"><FluentIcon icon="dismiss-20-regular" :width="18" /></button></header><div class="uri-help-content"><p>选择要抽取的分类；选择「全部」时不附带 category 参数，由 API 从全部分类随机返回。</p><div class="category-chips quote-config-chips"><button type="button" class="category-chip" :class="{ active: !draft.quoteApiCategories?.length }" @click="draft.quoteApiCategories = []">全部</button><button v-for="category in quoteCategories" :key="category" type="button" class="category-chip" :class="{ active: draft.quoteApiCategories?.includes(category) }" @click="toggleQuoteCategory(category)">{{ category }}</button><span v-if="quoteCategoryLoading" class="quote-config-hint">正在获取分类…</span></div><div class="setting-row quote-weight-toggle"><div><h3>启用分类权重</h3><p>开启后每次仅按权重随机选择一个分类请求 API；关闭时按所选分类整体随机。</p></div><button type="button" class="switch" :class="{ on: draft.quoteApiCategoryWeightsEnabled }" :disabled="!draft.quoteApiCategories?.length" @click="toggleCategoryWeights"><i></i></button></div><div v-if="draft.quoteApiCategoryWeightsEnabled && draft.quoteApiCategories?.length" class="category-weight-list"><label v-for="category in draft.quoteApiCategories" :key="category" class="category-weight-row"><span>{{ category }}</span><input type="number" min="0" max="9999" :value="categoryWeight(category)" @input="setCategoryWeight(category, $event)" /></label></div></div><footer><button type="button" class="save-button" @click="quoteConfigOpen = false">完成</button></footer></section></div>
  </section>
</template>
